// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint128).max);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();
        uint256 balanceBefore = address(c).balance;
        uint256 storedBalanceBefore = c.balance();
        bool withdrew;
        vm.prank(actor);
        try c.withdrawAll() { withdrew = true; } catch { withdrew = false; }
        uint256 balanceAfter = address(c).balance;
        uint256 storedBalanceAfter = c.balance();
        uint256 actorCredit = c.credit(actor);
        bool invariantOk;
        if (withdrew) {
            invariantOk = (actorCredit == 0) && (balanceAfter == storedBalanceAfter);
        } else {
            invariantOk = true;
        }
        assertTrue(invariantOk);
    }
}

