pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= 1 ether);
        // Deposit first to give the actor credit
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        // Record ETH balance before withdrawAll
        uint256 ethBefore = actor.balance;
        vm.prank(actor);
        c.withdrawAll();
        uint256 ethAfter = actor.balance;
        // After withdrawAll, actor's ETH balance must have increased
        assertTrue(ethAfter > ethBefore);
    }
}

