contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0) && actor != address(this));
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();
        uint256 balanceBeforeWithdraw = address(c).balance;
        vm.prank(actor);
        c.withdrawAll();
        uint256 balanceAfterWithdraw = address(c).balance;
        assertTrue(balanceAfterWithdraw == balanceBeforeWithdraw - withdrawAmount);
    }
}
